const SRC = JSON.parse(fs.readFileSync(path.join(__dirname, 'src_g3s2_social_u1.json'), 'utf8'));
const OUT = path.join(__dirname, '..', 'data', 'g3s2_social_u1.js');
const DIR = '1단원_사회변화와다양한문화';
