const TN = (a1, a2, watch, min) => ({ ask: [a1, a2], watch, min });
const nm = (s) => String(s || '').replace(/\*\*/g, '');
const SL = (k, i) => SRC[k].slides.find(x => x.i === i);
const BD = (k) => SRC[k].board_data;
const lines = (sl) => (sl.answer.length ? sl.answer : sl.items);
/* 원문 줄 → 카드: 「**X** — Y」 는 이름 X · 아래 줄 Y / 그 밖은 이름 = 첫 굵은 말 · 아래 줄 = 원문 문장 그대로 / 굵은 말이 없으면 이름 = 문장 */
const split = (t) => { const m = t.match(/^[○✕]?\*\*(.+?)\*\*\s*—\s*(.*)$/); if (m) return [m[1], nm(m[2])]; const b = t.match(/\*\*(.+?)\*\*/); if (b) return [b[1], nm(t)]; return [nm(t), '']; };
const cardFig = (k, i, emojis, chain) => ({ k: chain ? 'chain' : 'tools', items: lines(SL(k, i)).map((t, j) => { const [n, kind] = split(t); return { emoji: emojis[j % emojis.length], name: n, kind: kind || undefined }; }) });
const noteFig = (k, i, title) => ({ k: 'note', title, items: lines(SL(k, i)) });

/* 1학기 2단원 마지막 차시(u2_l18 「일상에서 만나는 과거」 정리) 출구 — 1세대 데이터에서 그대로 읽는다 */
const PREV_EXIT = (() => { const L = {}; const c = { window: { LESSONS: L }, LESSONS: L, document: { getElementById: () => null } }; c.window.window = c.window; vmm.createContext(c); vmm.runInContext(fs.readFileSync(path.join(__dirname, '..', 'data', 'g3_social_u2.js'), 'utf8'), c); return L.u2_l18.slides.find(s => s.block === 'exit_ticket').data.items; })();

