  u1_l06: () => { const b = BD('u1_l06'); return { k: 'note', title: '가려진 글자를 찾아요', items: b.GP_KEY.map(g => g.no + ' ' + g.dir + ' — ' + g.word.map((c, j) => g.hide.indexOf(j) >= 0 ? '**' + c + '**' : c).join('').replace(/\*\*\*\*/g, '')) }; },
