  u1_l10: () => { const b = BD('u1_l10'); return { k: 'groups', bins: [{ name: '탑에 쌓아요(바람직한 태도)', emoji: '🧱', tone: 't0', items: b.TW_BLOCK.filter(x => x.good).map(x => x.text) }, { name: '탑이 기울어요', emoji: '⚠️', tone: 'x', items: b.TW_BLOCK.filter(x => !x.good).map(x => x.text) }] }; },
  u1_l11: () => { const b = BD('u1_l11'); const bus = BUS(b); return { k: 'sort2', a: { name: '○ 알맞아요 — 힌트를 따라요', items: b.BS_SAY.filter(x => x.ok).map(x => x.text + ' → ' + x.hint) }, b: { name: '✗ 알맞지 않아요 — 힌트를 버려요', items: b.BS_SAY.filter(x => !x.ok).map(x => x.text), hint: '찾은 버스: **' + bus.no + '번 ' + { 빨강: '빨간', 노랑: '노란', 파랑: '파란', 초록: '초록' }[bus.color] + ' 버스(' + bus.city + ')**' } }; },
  u1_l12: () => { const b = BD('u1_l12'); return { k: 'groups', bins: b.DG_TOPIC.map((t, i) => ({ name: t, items: b.DG_CARD.filter(c => c.t === i).map(c => c.text) })) }; }
