/* 버스 찾기: 알맞은 설명의 힌트만 따라 버스를 지운다(짝수·홀수·색·ㄴ 받침) — 게이트 M 이 따로 셈해 대조 */
function BUS(b) { const hasN = (s) => [...s].some(ch => { const c = ch.charCodeAt(0) - 0xAC00; return c >= 0 && c < 11172 && c % 28 === 4; });
  let left = b.BS_BUS.slice(); b.BS_SAY.filter(x => x.ok).forEach(x => { left = left.filter(bus => !(x.off === 'even' && bus.no % 2 === 0) && !(x.off === 'odd' && bus.no % 2 === 1) && !(x.off === bus.color) && !(x.off === 'nieun' && hasN(bus.city))); });
  if (left.length !== 1) throw new Error('버스 ' + left.length); return left[0]; }

